create TABLE IF NOT EXISTS FLYWAY_SCHEMA_HISTORY (
	INSTALLED_RANK NUMBER(38,0) NOT NULL,
	VERSION VARCHAR(50),
	DESCRIPTION VARCHAR(200),
	TYPE VARCHAR(20) NOT NULL,
	SCRIPT VARCHAR(1000) NOT NULL,
	CHECKSUM NUMBER(38,0),
	INSTALLED_BY VARCHAR(100) NOT NULL,
	INSTALLED_ON TIMESTAMP_LTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP(),
	EXECUTION_TIME NUMBER(38,0) NOT NULL,
	SUCCESS BOOLEAN NOT NULL,
	primary key (INSTALLED_RANK)
);
create view IF NOT EXISTS CHANNEL_DIM_BV(
	CHANNEL_ID,
	ORDER_CHANNEL_NM,
	FULFILLMENT_CHANNEL_NM,
	ORDER_CHANNEL_HIERARCHY_L3_NM,
	ORDER_CHANNEL_HIERARCHY_L2_NM,
	ORDER_CHANNEL_HIERARCHY_L1_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L3_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L2_NM,
	FULFILLMENT_CHANNEL_HIERARCHY_L1_NM,
	SOURCE_SYSTEM_NM,
	HIERARCHY_SOURCE_SYSTEM_NM,
	BRAND_ID,
	CDM_LOAD_DT,
	CDM_UPDATE_DT,
	LOAD_ID COMMENT 'Load Identifier specifies the Batch that inserted the record into the table.',
	LOAD_DTTM COMMENT 'Load Datetime is the date and time in UTC when the record was created. For example, 2021-08-11T15:02:24Z.',
	UPDATE_ID COMMENT 'Update Identifier specifies the batch id used for the update of the record.',
	UPDATE_DTTM COMMENT 'Update Datetime is the date and time in UTC when the record was last updated. For example, 2021-08-11T15:02:24Z.'
) as 
SELECT CHANNEL_DIM.CHANNEL_ID,CHANNEL_DIM.ORDER_CHANNEL_NM,CHANNEL_DIM.FULFILLMENT_CHANNEL_NM,CHANNEL_DIM.ORDER_CHANNEL_HIERARCHY_L3_NM,CHANNEL_DIM.ORDER_CHANNEL_HIERARCHY_L2_NM,CHANNEL_DIM.ORDER_CHANNEL_HIERARCHY_L1_NM,CHANNEL_DIM.FULFILLMENT_CHANNEL_HIERARCHY_L3_NM,CHANNEL_DIM.FULFILLMENT_CHANNEL_HIERARCHY_L2_NM,CHANNEL_DIM.FULFILLMENT_CHANNEL_HIERARCHY_L1_NM,CHANNEL_DIM.SOURCE_SYSTEM_NM,CHANNEL_DIM.HIERARCHY_SOURCE_SYSTEM_NM,CHANNEL_DIM.BRAND_ID,CHANNEL_DIM.CDM_LOAD_DT,CHANNEL_DIM.CDM_UPDATE_DT,CHANNEL_DIM.LOAD_ID,CHANNEL_DIM.LOAD_DTTM,CHANNEL_DIM.UPDATE_ID,CHANNEL_DIM.UPDATE_DTTM
FROM IDM_DEV.COREDIM.CHANNEL_DIM ;
create view IF NOT EXISTS CUSTOMER_ARCHIVE_STATUS_BV(
	SUBSCRIBER_KEY COMMENT 'This ID will be used to populate column titled archive status in cust_profile_plr and customer_dim tables. Currently this column do not exist in those tables. Archival status tracking should be maintained at the DD Profile ID level (subscriber key in trg_mktg_member_plr)cdm_prod.customer_status_type.customer_id = cdm.prod.trg_mktg_member_plr.subscriber_key ',
	CUSTOMER_STATUS_TYPE_CD COMMENT 'A code that represents the status of the customer. Eg. CCA',
	BRAND_ID COMMENT 'Brand Identifier associated with the transaction',
	CUSTOMER_STATUS_EFFECTIVE_DT COMMENT 'The Date the Customer Status goes into effect',
	CUSTOMER_STATUS_EXPIRY_DT COMMENT 'his is the Date that the Customer Status Becomes ineffective',
	SOURCE_SYSTEM_NM COMMENT 'The POS System used to load the transaction  information\n',
	LOAD_TYP COMMENT 'Indicates whether data is part of a large historical data pull or was added from a smaller data pull (daily, weekly etc.) \n',
	LOAD_ID COMMENT 'This is the User Identifier of the Person or Process that Loaded the Table',
	LOAD_DTTM COMMENT 'The Date/Datetime the Record was Inserted',
	UPDATE_ID COMMENT 'This is the User Identifier of the Person or Process that Updated the Table',
	UPDATE_DTTM COMMENT 'The Date/Datetime the Record was Updated'
) as 
SELECT CUSTOMER_ARCHIVE_STATUS.SUBSCRIBER_KEY,CUSTOMER_ARCHIVE_STATUS.CUSTOMER_STATUS_TYPE_CD,CUSTOMER_ARCHIVE_STATUS.BRAND_ID,CUSTOMER_ARCHIVE_STATUS.CUSTOMER_STATUS_EFFECTIVE_DT,CUSTOMER_ARCHIVE_STATUS.CUSTOMER_STATUS_EXPIRY_DT,CUSTOMER_ARCHIVE_STATUS.SOURCE_SYSTEM_NM,CUSTOMER_ARCHIVE_STATUS.LOAD_TYP,CUSTOMER_ARCHIVE_STATUS.LOAD_ID,CUSTOMER_ARCHIVE_STATUS.LOAD_DTTM,CUSTOMER_ARCHIVE_STATUS.UPDATE_ID,CUSTOMER_ARCHIVE_STATUS.UPDATE_DTTM
FROM IDM_DEV.COREDIM.CUSTOMER_ARCHIVE_STATUS ;
